(()=>{
 const previous=EmberViewport.prototype.render;
 EmberViewport.prototype.render=function(particles,settings,grid,light){
  const T=Ember3D,editor=window.emberPathEditor;
  if(!this.pathGuide){const geometry=new T.BufferGeometry();geometry.setAttribute('position',new T.BufferAttribute(new Float32Array(512),3).setUsage(T.DynamicDrawUsage));this.pathGuide=new T.Line(geometry,new T.LineBasicMaterial({color:0xc6a6ff,transparent:true,opacity:.8,depthTest:false}));this.pathGuide.frustumCulled=false;this.pathGuide.renderOrder=990;this.scene.add(this.pathGuide);this.pathHandles=[];const sphere=new T.SphereGeometry(4,12,8);for(let i=0;i<21;i++){const handle=new T.Mesh(sphere,new T.MeshBasicMaterial({color:0xb6a0ff,depthTest:false}));handle.userData.pathIndex=i;handle.renderOrder=1000;this.pathHandles.push(handle);this.scene.add(handle);}this.pathHead=new T.Mesh(new T.SphereGeometry(3,12,8),new T.MeshBasicMaterial({color:0xffcf69,depthTest:false}));this.pathHead.renderOrder=1001;this.scene.add(this.pathHead);this.installPathDragging();}
  const effect=editor?.effect(),signature=effect?JSON.stringify([effect.id,effect.shape,effect.motion,effect.positionX,effect.positionY,effect.positionZ,(effect.animation?.keys||[]).filter(k=>['positionX','positionY','positionZ'].includes(k.property))]):'';if(signature!==this.pathSignature){this.pathSignature=signature;this.pathPoints=effect?EmberMotionPath.read(effect):[];}const points=this.pathPoints||[],show=points.length>=2&&(grid||editor?.editing);this.pathGuide.visible=this.pathHead.visible=show;for(const handle of this.pathHandles)handle.visible=false;
  if(show){const center=EmberMotionPath.centerZ(effect);if(this.pathGeometrySignature!==signature){this.pathGeometrySignature=signature;const duration=points.at(-1).time,times=[...new Set([...points.map(p=>p.time),...Array.from({length:97},(_,i)=>duration*i/96)])].sort((a,b)=>a-b),array=this.pathGuide.geometry.attributes.position.array;times.forEach((time,index)=>{const s=EmberAnimation.evaluate(effect,time);array.set([s.positionX||0,s.positionY||0,(s.positionZ||0)+center],index*3);});this.pathGuide.geometry.setDrawRange(0,times.length);this.pathGuide.geometry.attributes.position.needsUpdate=true;}points.forEach((p,index)=>{const handle=this.pathHandles[index];if(!handle)return;handle.position.set(p.x,p.y,p.z+center);handle.visible=!!editor.editing;handle.scale.setScalar(index===editor.selected?1.5:1);handle.material.color.set(index===editor.selected?0xff9fd8:0xb6a0ff);});const current=EmberAnimation.evaluate(effect,editor.time());this.pathHead.position.set(current.positionX||0,current.positionY||0,(current.positionZ||0)+center);}
  previous.call(this,particles,settings,grid,light);
 };
 EmberViewport.prototype.installPathDragging=function(){
  const T=Ember3D,ray=new T.Raycaster(),pointer=new T.Vector2(),intersection=new T.Vector3();let dragPlane=null,pointerId=null,grabOffset=new T.Vector3();
  const setRay=event=>{const rect=this.canvas.getBoundingClientRect();pointer.set((event.clientX-rect.left)/rect.width*2-1,-(event.clientY-rect.top)/rect.height*2+1);ray.setFromCamera(pointer,this.camera);};
  this.canvas.addEventListener('pointerdown',event=>{const editor=window.emberPathEditor;if(!editor?.editing||event.button!==0)return;setRay(event);const hit=ray.intersectObjects(this.pathHandles.filter(handle=>handle.visible))[0];if(!hit)return;const normal=editor.plane==='XZ'?new T.Vector3(0,1,0):editor.plane==='YZ'?new T.Vector3(1,0,0):new T.Vector3(0,0,1);if(Math.abs(ray.ray.direction.dot(normal))<.05){toast('Choose another drag plane or camera view');return;}dragPlane=new T.Plane().setFromNormalAndCoplanarPoint(normal,hit.object.position);if(!ray.ray.intersectPlane(dragPlane,intersection))return;grabOffset.copy(hit.object.position).sub(intersection);if(!editor.begin(hit.object.userData.pathIndex)){dragPlane=null;return;}pointerId=event.pointerId;this.canvas.setPointerCapture(pointerId);event.preventDefault();event.stopImmediatePropagation();},true);
  this.canvas.addEventListener('pointermove',event=>{if(!dragPlane||event.pointerId!==pointerId)return;setRay(event);if(ray.ray.intersectPlane(dragPlane,intersection)){intersection.add(grabOffset);const editor=window.emberPathEditor;editor.move({x:intersection.x,y:intersection.y,z:intersection.z-EmberMotionPath.centerZ(editor.effect())},event.shiftKey);}event.preventDefault();event.stopImmediatePropagation();},true);
  const finish=(event,commit)=>{if(!dragPlane||event.pointerId!==pointerId)return;dragPlane=null;window.emberPathEditor?.finish(commit);if(this.canvas.hasPointerCapture(pointerId))this.canvas.releasePointerCapture(pointerId);pointerId=null;event.preventDefault();event.stopImmediatePropagation();};this.canvas.addEventListener('pointerup',event=>finish(event,true),true);this.canvas.addEventListener('pointercancel',event=>finish(event,false),true);this.canvas.addEventListener('lostpointercapture',event=>{if(dragPlane)finish(event,false);},true);
 };
})();
